using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

builder.Logging.SetMinimumLevel(LogLevel.Warning);

builder.Services.AddChatClient(chatClientBuilder =>
    chatClientBuilder
        .UseLogging()
        .UseOpenAIChatClient("gpt-4o-mini-2024-07-18"));

builder.Services.AddSingleton<Notebook>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notebook = host.Services.GetRequiredService<Notebook>();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            Console.ForegroundColor = ConsoleColor.DarkYellow;
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            Console.ResetColor();
            return WebSearchTool.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a given query. Returns a list of relevant results with titles, snippets, and URLs."),
    AIFunctionFactory.Create(
        ([Description("Title or label for this note")] string title,
         [Description("The content to save")] string content) =>
        {
            Console.ForegroundColor = ConsoleColor.DarkCyan;
            Console.WriteLine($"  📝 Saving note: \"{title}\"");
            Console.ResetColor();
            notebook.AddNote(title, content);
            return $"Note '{title}' saved successfully.";
        },
        "save_note",
        "Saves a research note with a title and content for later reference when writing the final summary."),
    AIFunctionFactory.Create(
        () =>
        {
            Console.ForegroundColor = ConsoleColor.DarkCyan;
            Console.WriteLine("  📋 Reading all notes");
            Console.ResetColor();
            return notebook.GetAllNotes();
        },
        "get_notes",
        "Retrieves all previously saved research notes to review findings before writing the summary."),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly and produce a clear summary.

        Follow this process:
        1. Break the topic into 2-3 key subtopics or questions to investigate.
        2. Use the web_search tool to find information on each subtopic.
        3. Use the save_note tool to record key findings as you go — include sources.
        4. After gathering enough information, use get_notes to review your findings.
        5. Produce a well-structured final summary with sections, key findings, and source references.

        Be thorough but concise. Always cite your sources.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools",
    tools: tools);

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔬 Research Agent Ready        ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine();

Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.DarkGray;
Console.WriteLine($"Researching: \"{topic}\"...");
Console.ResetColor();
Console.WriteLine();

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(topic, options: runOptions);

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("═══════════════ Research Summary ═══════════════");
Console.ResetColor();
Console.WriteLine(response.Text);
Console.WriteLine();

/// <summary>
/// Simple in-memory notebook for storing research notes.
/// </summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"--- Note {i + 1}: {note.Title} ---");
            sb.AppendLine(note.Content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

/// <summary>
/// Simulated web search that returns plausible results.
/// Replace with a real search API (e.g., Bing Search API) for production use.
/// </summary>
static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Attempt to use a real search API if configured; otherwise return simulated results.
        var searchApiKey = Environment.GetEnvironmentVariable("BING_SEARCH_API_KEY");
        if (!string.IsNullOrEmpty(searchApiKey))
        {
            return await SearchWithBingAsync(query, searchApiKey);
        }

        return GetSimulatedResults(query);
    }

    private static async Task<string> SearchWithBingAsync(string query, string apiKey)
    {
        try
        {
            using var request = new HttpRequestMessage(HttpMethod.Get,
                $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5");
            request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

            var response = await HttpClient.SendAsync(request);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed ({ex.Message}). Using simulated results.\n\n{GetSimulatedResults(query)}";
        }
    }

    private static string GetSimulatedResults(string query)
    {
        return $$"""
            Search results for: "{{query}}"

            1. Title: "{{query}} - Wikipedia Overview"
               URL: https://en.wikipedia.org/wiki/{{Uri.EscapeDataString(query)}}
               Snippet: Comprehensive encyclopedia article covering the key aspects, history, and significance of {{query}}.

            2. Title: "Understanding {{query}} - A Complete Guide"
               URL: https://www.example.com/guide/{{Uri.EscapeDataString(query)}}
               Snippet: An in-depth guide exploring the fundamentals, current developments, and future outlook of {{query}}.

            3. Title: "Latest Research on {{query}}"
               URL: https://scholar.example.com/{{Uri.EscapeDataString(query)}}
               Snippet: Recent academic publications and research findings related to {{query}}, including peer-reviewed studies and meta-analyses.

            4. Title: "{{query}}: Expert Analysis and Insights"
               URL: https://www.analysis-example.com/{{Uri.EscapeDataString(query)}}
               Snippet: Expert commentary and analysis on the most important trends and developments in {{query}}.

            5. Title: "{{query}} - News and Updates"
               URL: https://news.example.com/topic/{{Uri.EscapeDataString(query)}}
               Snippet: The latest news coverage and updates about {{query}} from reliable news sources around the world.

            Note: These are simulated search results. Set the BING_SEARCH_API_KEY environment variable to use real Bing Web Search results.
            """
        ;
    }
}

